/// <summary>
///
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[DataEventHandler(tableStr(CustTable), DataEventType::Updating)]
public static void CustTable_onUpdating(Common sender, DataEventArgs e)
{
    CustTable custTable = sender;
    CustTrans custTrans;

    update_recordset custTrans
            setting MZNAGDescription = custTable.MZNAGDescription
            where custTrans.AccountNum == custTable.AccountNum;

}
